package com.aliworld.jreader.source
import com.aliworld.jreader.core.model.*
import org.jsoup.Jsoup
actual object HtmlParser {actual fun feed(html:String)=Jsoup.parse(html,"https://e-hentai.org/").select("table.itg tr").mapNotNull{r->val a=r.selectFirst("a[href*=/g/]")?:return@mapNotNull null;Manga(a.absUrl("href"),SourceId.EHENTAI,r.selectFirst(".glink")?.text()?:a.text(),image(r.selectFirst("img")),category=r.selectFirst(".cn,.cs")?.text().orEmpty())}.distinctBy{it.id};actual fun next(html:String)=Jsoup.parse(html,"https://e-hentai.org/").selectFirst("a[href*='next=']")?.attr("href")?.substringAfter("next=")?.substringBefore('&');actual fun detail(html:String,url:String):Pair<Manga,List<String>>{val d=Jsoup.parse(html,url);val m=Manga(url,SourceId.EHENTAI,d.selectFirst("#gn")?.text().orEmpty().ifBlank{"Untitled"},image(d.selectFirst("#gd1 img")),category=d.selectFirst("#gdc")?.text().orEmpty(),uploader=d.selectFirst("#gdn a")?.text().orEmpty(),pageCount=d.selectFirst("#gdd tr:contains(Length) .gdt2")?.text().orEmpty());return m to d.select("#gdt a").map{it.absUrl("href")}.filter(String::isNotBlank)};actual fun image(html:String)=Jsoup.parse(html).selectFirst("#img")?.absUrl("src");private fun image(e:org.jsoup.nodes.Element?):String{if(e==null)return "";val x=e.attr("data-src").ifBlank{e.attr("src")};return if(x.startsWith("//"))"https:$x"else x}}
